cats=list(dict.fromkeys(r['category'] for r in records))
intro='# Справочник врача по проблемам медицинских систем на 1С\n\nРабочая версия от 30 октября 2026 года. Исследование продолжается. Конфигурация больницы в Иванове неизвестна; ни одна карточка не проверена на её рабочих местах.\n\nИщите через «Найти на странице» по двум-трём словам, например «нет пациента», «остатков нет», «подпись МО». В PDF используйте поиск текста. Сначала сверяйте операцию и версию: одинаковый симптом имеет разные причины. СЭМД — структурированный электронный медицинский документ; ЭМК — электронная медицинская карта; ШМД — шаблон медицинского документа; РЭМД — реестр электронных медицинских документов; ТАП — талон амбулаторного пациента.\n\nНе повторяйте назначения, выписку, подпись или отправку, пока не проверено состояние исходной записи. Не удаляйте медицинские документы. Настройки, права, обновления и сертификаты проверяет местная поддержка. На личном телефоне не сохраняйте данные пациентов. Если работа остановилась, действуйте по принятому в больнице порядку работы при недоступности МИС.\n\n**Как читать отметки.** «Подтверждено» означает, что источник описывает правило или исправление, но не обязательно успешное решение конкретного обращения. «Подтверждено пользователем» — есть сообщение об успехе. «Возможно» — только обоснованная проверка или гипотеза. «Не решено» — надёжного решения не найдено. Локальная проверка нужна во всех случаях. Безопасные действия по проверке и обращению в поддержку составлены редакционно; они не выдаются за дословную инструкцию разработчика.\n\n'
def card(r):
    s=f'<a id="error-{r["id"]}"></a>\n\n### № {r["id"]} — {r["title"]}\n\n'
    s+=f'**Где возникает:** {r["workflow"]}.\n\n**Текст ошибки / Что искать:** '+(f'Код: {r["error_code"]}. ' if r['error_code'] else '')+(f'«{r["original_error_text"]}». ' if r['original_error_text'] else 'Полный текст сообщения не установлен; ищите по коду и уточняющим словам. ')+ '; '.join(r['alternative_search_phrases'])+'.\n\n'
    s+=f'**Почему:** {r["cause"]}\n\n**Что делать:**\n\n'+'\n'.join(f'{i}. {v}' for i,v in enumerate(r['physician_instructions'],1))
    s+=f'\n\n**Если не помогло:** {r["escalation_instructions"]}\n\n'
    s+='**Источник:** '+', '.join(f'[Открыть источник]({u})' for u in r['source_urls'])+(f' — {r["source_locator"]}' if r['source_locator'] else '')+'.\n\n'
    s+=f'**Проверено:** {"; ".join(r["evidence_status"])}. {r["evidence_note"]}\n\n**Конфигурация и версия:** {r["software_product"]}; {r["software_version"]}. Источник: {r["source_date"]}. Проверка: {DATE}.\n\n'
    return s
md=intro+'## Оглавление\n\n'+'\n'.join(f'- [{c}](#category-{i})' for i,c in enumerate(cats,1))+'\n\n'
for i,c in enumerate(cats,1):
    md+=f'<a id="category-{i}"></a>\n\n## {c}\n\n'
    group=[r for r in records if r['category']==c]
    md+='\n'.join(f'- [№ {r["id"]} — {r["title"]}](#error-{r["id"]})' for r in group)+'\n\n'
    md+=''.join(card(r) for r in group)
(ROOT/'doctor_guide.md').write_text(md)
